-- Trigger WITH options, procedure FOR REPLICATION, and EXECUTE AS principals with quotes
CREATE TRIGGER tr ON t WITH EXECUTE AS CALLER INSTEAD OF UPDATE NOT FOR REPLICATION AS BEGIN SELECT 1; END;
GO
CREATE TRIGGER tr ON t WITH ENCRYPTION, EXECUTE AS 'o''brien' AFTER INSERT AS SELECT 1;
GO
CREATE TRIGGER tr ON DATABASE WITH EXECUTE AS SELF FOR CREATE_TABLE AS PRINT 'x';
GO
CREATE PROCEDURE p @a int = 1 WITH ENCRYPTION FOR REPLICATION AS SELECT @a;
GO
CREATE PROCEDURE p WITH EXECUTE AS 'it''s' AS SELECT 1;
GO
CREATE PROCEDURE p FOR REPLICATION AS SELECT 1;
